package com.hellokaton.blade;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Map;
import java.io.*;

public class EnvironmentTest {

    @Test
    public void testOfMethod() throws IOException {
        // Create a temporary properties file with required properties
        File tempFile = File.createTempFile("application", ".properties");
        try (PrintWriter out = new PrintWriter(new OutputStreamWriter(new FileOutputStream(tempFile), "UTF-8"))) {
            out.println("app.version=0.0.2");
            out.println("app.lang=cn.");
        }

        // Load Environment from file location
        Environment envFromFile = Environment.of("file:" + tempFile.getAbsolutePath());
        assertNotNull("Environment should not be null when loaded from file", envFromFile);
        assertEquals("0.0.2", envFromFile.getOrNull("app.version"));
        assertEquals("cn.", envFromFile.getOrNull("app.lang"));

        // Load Environment from classpath resource
        Environment envFromClasspath = Environment.of("classpath:application.properties");
        assertNotNull("Environment should not be null when loaded from classpath", envFromClasspath);
        assertEquals("0.0.2", envFromClasspath.getOrNull("app.version"));
        assertEquals("cn.", envFromClasspath.getOrNull("app.lang"));

        // Verify using toMap()
        Map<String, String> mapFromFile = envFromFile.toMap();
        assertEquals("0.0.2", mapFromFile.get("app.version"));
        assertEquals("cn.", mapFromFile.get("app.lang"));

        Map<String, String> mapFromClasspath = envFromClasspath.toMap();
        assertEquals("0.0.2", mapFromClasspath.get("app.version"));
        assertEquals("cn.", mapFromClasspath.get("app.lang"));

        // Set a new property and verify
        envFromFile.set("app.name", "TestApp");
        assertEquals("TestApp", envFromFile.getOrNull("app.name"));

        // Clean up temporary file
        tempFile.deleteOnExit();
    }
}

