<COVER>@Slf4j
@NoArgsConstructor
public final class DynamicContext {

<COVER>    private static final ClassReader classpathReader = new ClassPathClassReader();
<COVER>    private static final ClassReader jarReader       = new JarReaderImpl();
    private static final String      SUFFIX_JAR      = ".jar";

<COVER>    private static boolean isJarContext = false;

    public static void init(Class<?> clazz) {
<COVER>        String rs = clazz.getResource("").toString();
<COVER>        if (rs.contains(SUFFIX_JAR)) {
